from typing import List

def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    rows = len(grid)
    cols = len(grid[0])
    for r in range(rows):
        if r % 2 == 0:
            # Traverse left to right, skipping every alternate cell
            for c in range(0, cols, 2):
                result.append(grid[r][c])
        else:
            # Traverse right to left, skipping every alternate cell
            for c in range(cols - 1, -1, -2):
                result.append(grid[r][c])
    return [result[i] for i in range(len(result)) if i % 2 == 0]

def findValidPair(s: str) -> str:
    from collections import Counter
    counts = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            first_digit = int(s[i])
            second_digit = int(s[i + 1])
            if counts[s[i]] == first_digit and counts[s[i + 1]] == second_digit:
                return s[i] + s[i + 1]
    return ""

