def largestInteger(nums: List[int], k: int) -> int:
    count = {}
    n = len(nums)

    # Count occurrences of each number in all k-sized subarrays
    for i in range(n - k + 1):
        seen = set()
        for j in range(k):
            seen.add(nums[i + j])
        for num in seen:
            if num in count:
                count[num] += 1
            else:
                count[num] = 1

    # Find the largest number that appears in exactly one k-sized subarray
    largest = -1
    for num, occurrences in count.items():
        if occurrences == 1:
            largest = max(largest, num)

    return largest

