def maxSum(nums: List[int]) -> int:
    best = float('-inf')
    for start in range(len(nums)):
        seen = set()
        total = 0
        for end in range(start, len(nums)):
            if nums[end] in seen:
                break
            seen.add(nums[end])
            total += nums[end]
            best = max(best, total)
    return best

