from typing import List

def minCost(n: int, cost: List[List[int]]) -> int:
    # Initialize a DP array to store the minimum costs for each color pair
    dp = [[float('inf')] * 3 for _ in range(3)]
    # Initialize the pair states from the first and last house
    for left_color in range(3):
        for right_color in range(3):
            if left_color != right_color:
                dp[left_color][right_color] = cost[0][left_color] + cost[n - 1][right_color]

    # Process houses in pairs inward
    for k in range(1, n // 2):
        next_dp = [[float('inf')] * 3 for _ in range(3)]
        for left_color in range(3):
            for right_color in range(3):
                if dp[left_color][right_color] < float('inf'):
                    for new_left_color in range(3):
                        for new_right_color in range(3):
                            if new_left_color != left_color and new_right_color != right_color and new_left_color != new_right_color:
                                next_dp[new_left_color][new_right_color] = min(
                                    next_dp[new_left_color][new_right_color], 
                                    dp[left_color][right_color] + cost[k][new_left_color] + cost[n - 1 - k][new_right_color]
                                )
        dp = next_dp

    # Find the minimum cost among all valid colorings
    return min(dp[left_color][right_color] for left_color in range(3) for right_color in range(3))

from typing import List
import heapq

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    event_map = []

    # Process events to handle OFFLINE and MESSAGE
    for event in sorted(events, key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1)):
        event_type, timestamp, *data = event
        timestamp = int(timestamp)
        if event_type == "OFFLINE":
            user_id = int(data[0])  # Extract id<number> directly
            # Set user offline
            online_status[user_id] = False
            # Schedule return after 60 time units
            heapq.heappush(event_map, (timestamp + 60, user_id))
        elif event_type == "MESSAGE":
            # Process returning users if their time has come
            while event_map and event_map[0][0] <= timestamp:
                _, user_id = heapq.heappop(event_map)
                online_status[user_id] = True
            mentions_string = data[0]
            # Split mentions
            if mentions_string == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif mentions_string == "HERE":
                for i in range(numberOfUsers):
                    if online_status[i]:
                        mentions[i] += 1
            else:
                mentioned_ids = mentions_string.split()
                for mention in mentioned_ids:
                    user_id = int(mention[2:])  # Extract id<number>
                    mentions[user_id] += 1

    return mentions
